#!/usr/bin/env node
/**
 * tractor-cens.mjs — LA PORTA DE LA REGLA SAGRADA
 *
 * PER QUÈ EXISTIX (auditoria Seient Núm. 5, 260831):
 *
 *   El Mestre va preguntar per què la IAIA «oblidava» una regla explícita de
 *   la seua pròpia Wiki. La resposta empírica és que no l'oblidava: l'obeïa
 *   ignorant-la, perquè tres documents executius li ho ordenen.
 *
 *     .agents/AGENTS.md §1        «L'autoritat executiva viu EXCLUSIVAMENT a
 *                                  .agents/skills/»
 *     .agents/skills/00_INDEX…    «Qualsevol altra regla trobada fora d'aquesta
 *                                  carpeta no té valor executiu i HA DE SER
 *                                  IGNORADA»
 *     .agents/BOOTSTRAP.md §2.3   «les regles executives residixen ÚNICAMENT
 *                                  a .agents/»
 *
 *   La «Regla Sagrada» d'enumerar totes les Petorretes vivia només a
 *   _wiki_de_poble/01_ser/03_equip_ia.md:54.
 *
 *   Una regla que ha de ser inevitable no pot ser prosa dins d'una zona
 *   declarada no-executiva. Ha de ser DADES amb PORTA. Això és la porta.
 *
 * LLEIS
 *   C1 · El cens existix, és vàlid i no té ids duplicats.
 *   C2 · Cap document que parle del Consell com a CONJUNT pot deixar-se
 *        membres actives fora.
 *   C3 · Cap document pot anomenar una IA que no és al cens (ni «Codex» ni
 *        cap altra) com si en formara part.
 *   C4 · Cap xifra literal («onze», «dotze», «12 IAs») pot contradir el
 *        recompte real del cens.
 *   C5 · La skill executiva multi-agent-review ha de citar el cens, no
 *        llistar noms amb un «etc.».
 *
 * Ús:
 *   node tooling/gates/tractor-cens.mjs
 *   node tooling/gates/tractor-cens.mjs --arrel ../
 *
 * Eixides: 0 net · 1 infracció · 2 error d'execució.
 */

import { readFileSync, existsSync, readdirSync, statSync } from 'node:fs';
import path from 'node:path';

const ARREL = (() => {
  const i = process.argv.indexOf('--arrel');
  return path.resolve(i > -1 ? process.argv[i + 1] : process.cwd());
})();

const R = (rel) => path.join(ARREL, rel);
const CENS = '.agents/consell.json';

const infraccions = [];
const OK = [];
const falla = (llei, fitxer, linia, missatge) =>
  infraccions.push({ llei, fitxer, linia, missatge });
const passa = (llei) => OK.push(llei);

/* ══════════════════════════════════════════════════════════════════
   C1 · El cens existix i és vàlid
   ══════════════════════════════════════════════════════════════════ */
if (!existsSync(R(CENS))) {
  console.error(`❌ PARAT. No existix ${CENS}.`);
  console.error('   Sense cens no hi ha Regla Sagrada: només hi ha una frase en un document');
  console.error('   que la constitució obliga a ignorar. Crea el cens primer.');
  process.exit(2);
}

let cens;
try {
  cens = JSON.parse(readFileSync(R(CENS), 'utf8'));
} catch (e) {
  console.error(`❌ PARAT. ${CENS} no és JSON vàlid: ${e.message}`);
  process.exit(2);
}

const membres = (cens.membres || []).filter((m) => m.actiu !== false);
const noms = membres.map((m) => m.nom);
const ids = membres.map((m) => m.id);
const N = membres.length;

{
  const LLEI = 'C1 · Cens vàlid';
  const dup = ids.filter((x, i) => ids.indexOf(x) !== i);
  const senseCamp = membres.filter(
    (m) => !m.nom || !m.fortalesa || !m.debilitat || !m.rol
  );
  if (dup.length) {
    falla(LLEI, CENS, 0, `ids duplicats: ${[...new Set(dup)].join(', ')}`);
  }
  for (const m of senseCamp) {
    falla(LLEI, CENS, 0,
      `«${m.nom || m.id}» sense nom/fortalesa/debilitat/rol. La Regla Sagrada exigix respectar les característiques úniques de cadascuna: sense elles no es pot assignar rol.`);
  }
  if (!dup.length && !senseCamp.length) passa(LLEI);
}

/* ══════════════════════════════════════════════════════════════════
   Recorregut de documents
   ══════════════════════════════════════════════════════════════════ */
const SALTA = new Set([
  'node_modules', 'dist', 'build', 'coverage', '.git',
  '90_arxiu_historic', '_arxiu_wiki_de_poble', '.sdp-paperera'
]);

function arbre(rel, eixida = []) {
  const base = R(rel);
  if (!existsSync(base)) return eixida;
  for (const nom of readdirSync(base)) {
    if (SALTA.has(nom) || nom.startsWith('.quarantena')) continue;
    const abs = path.join(base, nom);
    const sub = path.join(rel, nom);
    if (statSync(abs).isDirectory()) arbre(sub, eixida);
    else if (nom.endsWith('.md') && !nom.toUpperCase().includes('BUNDLE')) eixida.push(sub);
  }
  return eixida;
}

const DOCS = [
  ...arbre('.agents'),
  ...arbre('_wiki_de_poble')
];

/* Un document «parla del Consell com a conjunt» si menciona el Consell o les
   Petorretes I anomena almenys tres membres. Menys de tres és una cita, no
   un cens: citar Qwen en una frase no obliga a anomenar-les totes. */
const LLINDAR_CENS = 3;
const PARLA_DEL_CONJUNT =
  /\b(el\s+consell|les\s+petorret|família\s+electrònica|familia\s+electronica)/i;

function nomsPresents(text) {
  return noms.filter((n) => {
    const esc = n.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    return new RegExp(`(^|[^\\w.-])${esc}([^\\w-]|$)`, 'i').test(text);
  });
}

/* ══════════════════════════════════════════════════════════════════
   C2 · Cap cens incomplet
   ══════════════════════════════════════════════════════════════════ */
{
  const LLEI = 'C2 · Cens incomplet';
  let net = true;
  for (const rel of DOCS) {
    if (rel.replace(/\\/g, '/') === CENS) continue;
    const text = readFileSync(R(rel), 'utf8');
    if (!PARLA_DEL_CONJUNT.test(text)) continue;
    const presents = nomsPresents(text);
    if (presents.length < LLINDAR_CENS) continue;
    if (presents.length === N) continue;
    net = false;
    const falten = noms.filter((n) => !presents.includes(n));
    falla(LLEI, rel, 0,
      `Parla del Consell i n'anomena ${presents.length} de ${N}. Falten: ${falten.join(', ')}.`);
  }
  if (net) passa(LLEI);
}

/* ══════════════════════════════════════════════════════════════════
   C3 · Cap membre inventada
   ══════════════════════════════════════════════════════════════════ */
{
  const LLEI = 'C3 · Membre fora del cens';
  const SOSPITOSES = Object.keys(cens.no_membres || {});
  let net = true;
  for (const rel of DOCS) {
    if (rel.replace(/\\/g, '/') === CENS) continue;
    const linies = readFileSync(R(rel), 'utf8').split('\n');
    linies.forEach((l, i) => {
      if (!PARLA_DEL_CONJUNT.test(l) && !/\bpetorret/i.test(l)) return;
      for (const s of SOSPITOSES) {
        const re = new RegExp(`(^|[^\\w-])${s}([^\\w-]|$)`, 'i');
        if (!re.test(l)) continue;
        net = false;
        falla(LLEI, rel, i + 1,
          `Anomena «${s}» com a membre del Consell i no és al cens. ${cens.no_membres[s]}`);
      }
    });
  }
  if (net) passa(LLEI);
}

/* ══════════════════════════════════════════════════════════════════
   C4 · Cap xifra que contradiga el cens
   ══════════════════════════════════════════════════════════════════ */
{
  const LLEI = 'C4 · Xifra contradictòria';
  // En valencià «nou» és alhora 9 i «nou/nova», i «deu» és 10 i «deu».
  // Per això la xifra NOMÉS compta si va enganxada a un substantiu del
  // Consell. Una porta amb falsos positius s'ignora, i una porta ignorada
  // no és una porta.
  const LLETRES = { huit: 8, nou: 9, deu: 10, onze: 11, dotze: 12, tretze: 13, catorze: 14 };
  // Sempre en PLURAL: en valencià «nou model» és «un model nou», no «nou models».
  // Exigir el plural elimina el fals positiu sense perdre cap cas real.
  const SUBSTANTIU = '(IAs|intel·ligències|models|proveïdors|proveidors|petorretes|ties|germanes)';
  let net = true;
  for (const rel of DOCS) {
    if (rel.replace(/\\/g, '/') === CENS) continue;
    const linies = readFileSync(R(rel), 'utf8').split('\n');
    linies.forEach((l, i) => {
      // Un nucli o subgrup explícit és un subconjunt, llevat que la mateixa
      // línia afirme el cens complet. L'excepció només afecta eixe recompte.
      const esSubconjunt = index => !PARLA_DEL_CONJUNT.test(l) &&
        /\b(?:nucli|subgrup)\s+de\s*$/iu.test(l.slice(0,index));
      // Xifra en lletra, enganxada al substantiu
      for (const [mot, val] of Object.entries(LLETRES)) {
        const re = new RegExp(`\\b${mot}\\s+${SUBSTANTIU}`, 'gi');
        for (const m of l.matchAll(re)) {
          if (val === N || esSubconjunt(m.index)) continue;
          net = false;
          falla(LLEI, rel, i + 1,
            `Diu «${mot}» (${val}) però el cens en té ${N}. → ${l.trim().slice(0, 88)}`);
        }
      }
      // Xifra en dígit, enganxada al substantiu
      for (const m of l.matchAll(new RegExp(`\\b(\\d{1,2})\\s+${SUBSTANTIU}`, 'gi'))) {
        const val = Number(m[1]);
        if (val === N || esSubconjunt(m.index)) continue;
        net = false;
        falla(LLEI, rel, i + 1,
          `Diu «${m[0]}» però el cens en té ${N}. → ${l.trim().slice(0, 88)}`);
      }
    });
  }
  if (net) passa(LLEI);
}

/* ══════════════════════════════════════════════════════════════════
   C5 · La skill executiva ha de citar el cens
   ══════════════════════════════════════════════════════════════════ */
{
  const LLEI = 'C5 · Skill executiva sense cens';
  const SKILL = '.agents/skills/core-consell-i-colmena/SKILL.md';
  if (!existsSync(R(SKILL))) {
    falla(LLEI, SKILL, 0, 'Absent. És l\'única skill executiva que governa el Consell.');
  } else {
    const text = readFileSync(R(SKILL), 'utf8');
    const cita = /consell\.json/.test(text);
    // Llista oberta = una MATEIXA LÍNIA amb dos o més membres i un «etc.».
    // Els `triggers_on` poden portar noms solts; això no és un cens obert.
    const llistaOberta = text.split('\n').some(
      (l) => /\betc\.?/i.test(l) && nomsPresents(l).length >= 2
    );
    if (!cita) {
      falla(LLEI, SKILL, 0,
        'No cita `.agents/consell.json`. Mentre la única font executiva porte la llista dins del text, l\'agent reproduirà eixa llista i no el cens.');
    }
    if (llistaOberta) {
      falla(LLEI, SKILL, 0,
        'Conté una llista de noms acabada en «etc.». És exactament la conducta que el Mestre va observar en si mateix: l\'agent no inventa res, reproduïx la llista parcial que la seua font executiva li dona.');
    }
    if (cita && !llistaOberta) passa(LLEI);
  }
}

/* ══════════════════════════════════════════════════════════════════
   INFORME
   ══════════════════════════════════════════════════════════════════ */
const banda = '─'.repeat(72);
console.log(`\n🗳️  TRACTOR DEL CENS — ${N} membres actives al Consell\n   ${noms.join(' · ')}\n${banda}`);

for (const l of OK) console.log(`  ✅ ${l}`);

if (infraccions.length) {
  const perLlei = new Map();
  for (const i of infraccions) {
    if (!perLlei.has(i.llei)) perLlei.set(i.llei, []);
    perLlei.get(i.llei).push(i);
  }
  console.log(`\n❌ INFRACCIONS (${infraccions.length})\n${banda}`);
  for (const [llei, llista] of perLlei) {
    console.log(`\n  ${llei}  (${llista.length})`);
    for (const i of llista.slice(0, 12)) {
      console.log(`    ${i.fitxer}${i.linia ? ':' + i.linia : ''}`);
      console.log(`      ↳ ${i.missatge}`);
    }
    if (llista.length > 12) console.log(`    … i ${llista.length - 12} més.`);
  }
  console.log(`\n${banda}`);
  console.log('La Regla Sagrada no es complix. Ara sí que és mecànica.\n');
  process.exit(1);
}

console.log(`\n${banda}\nEl cens i la doctrina diuen el mateix. Cap Petorreta oblidada.\n`);
process.exit(0);

/** Proves negatives de la Fortificació del Cervell.
 *  Cada prova injecta l'error que la porta vigila i exigeix que la porta parle.
 *  Una porta que no s'ha demostrat capaç de posar-se roja no és una comprovació. */
import {test} from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {spawnSync} from 'node:child_process';
import {fixture,validDoc,writeDoc,relay,REPO} from './helpers/documental.mjs';
import {loadContract,sections} from '../tooling/documental/core.mjs';
import {bindPlan,checkTurn,handoffDocument,inventory} from '../tooling/documental/turns.mjs';

const HUMAN='_wiki_de_poble/04_escriptori/01_produccio';

/** Torn planificat amb relleu, llest per a checkTurn. `abans` corre amb el fixture ja creat
 *  i abans d'obrir cap torn, per a que el que escriga entre a l'inventari inicial. */
function planned(t,abans=()=>{}) {
  const root=fixture(t);
  abans(root);
  const d=validDoc(root);writeDoc(root,d);
  const plan=validDoc(root,{route:'pla.implementacio',turn:d.turn,suffix:'pla'});writeDoc(root,plan);
  bindPlan(root,d.turn.turn_id,plan.file);relay(root,d.turn.turn_id);
  return {root,d,plan};
}
/** El marcador que `arrel()` exigeix per acceptar un --arrel imposat. */
function marcaArrel(root) {
  fs.mkdirSync(path.join(root,'.agents'),{recursive:true});
  fs.writeFileSync(path.join(root,'.agents/AGENTS.md'),'# Marcador d’arrel per a proves\n');
  return root;
}
function escriuZonaHumana(root,nom='260911_0645_material_del_mestre.md') {
  fs.mkdirSync(path.join(root,HUMAN),{recursive:true});
  fs.writeFileSync(path.join(root,HUMAN,nom),'Material humà. La IA no el pot tocar.\n');
  return `${HUMAN}/${nom}`;
}

// ── P-1 · La zona humana és invisible? ─────────────────────────────────────────
test('P-1 · la zona humana entra a l’inventari, només com a hash',t=>{
  const root=fixture(t);const rel=escriuZonaHumana(root);
  const inv=inventory(root);
  assert.ok(Object.hasOwn(inv,rel),'la zona humana ha de ser a l’inventari');
  assert.match(inv[rel],/^[a-f0-9]{64}$/,'de la zona humana només se n’ha de guardar el hash');
  assert.ok(!JSON.stringify(inv).includes('La IA no el pot tocar'),'mai el contingut');
});

test('P-1 · esborrar un fitxer de la zona humana posa el torn roig, amb nom propi',t=>{
  let rel;
  const {root,d}=planned(t,r=>{rel=escriuZonaHumana(r);});
  assert.equal(checkTurn(root,d.turn.turn_id).valid,true,'el torn ha de nàixer verd');
  fs.unlinkSync(path.join(root,rel));
  const r=checkTurn(root,d.turn.turn_id);
  assert.equal(r.valid,false,'esborrar material del Mestre ha de posar el torn roig');
  assert.match(r.errors.join('\n'),/Zona humana modificada/);
  assert.ok(r.errors.some(e=>e.includes(rel)),`l’error ha de nomenar ${rel}: ${r.errors.join(' | ')}`);
});

test('P-1 · modificar un fitxer de la zona humana també el posa roig',t=>{
  let rel;
  const {root,d}=planned(t,r=>{rel=escriuZonaHumana(r);});
  fs.appendFileSync(path.join(root,rel),'una línia que la IA no havia d’escriure\n');
  const r=checkTurn(root,d.turn.turn_id);
  assert.equal(r.valid,false);
  assert.ok(r.errors.some(e=>e.includes(rel)),r.errors.join(' | '));
});

// ── P-2 · El torn sobreviu al moviment d'un document? ──────────────────────────
test('P-2 · arxivar el pla d’un torn obert dóna diagnòstic amb nom, mai un ENOENT',t=>{
  const {root,d,plan}=planned(t);
  fs.unlinkSync(path.join(root,plan.file));
  let r;
  assert.doesNotThrow(()=>{r=checkTurn(root,d.turn.turn_id);},'checkTurn no pot estavellar-se: ha de diagnosticar');
  assert.equal(r.valid,false);
  const e=r.errors.join('\n');
  assert.match(e,/Pla absent o modificat/);
  assert.ok(e.includes(plan.file),`l’error ha de nomenar el pla: ${e}`);
  assert.ok(!/ENOENT/.test(e),`cap traça de Node a la cara de l’agent: ${e}`);
});

test('P-2 · el relleu deixa promoure un document a 10_actes i tancar el torn',t=>{
  const {root,d,plan}=planned(t);
  const desti='_wiki_de_poble/10_actes/'+path.basename(d.file);
  fs.mkdirSync(path.join(root,'_wiki_de_poble/10_actes'),{recursive:true});
  fs.renameSync(path.join(root,d.file),path.join(root,desti));
  // Sense relleu el torn queda mort: eixa és la fallada que motiva la funció.
  assert.match(checkTurn(root,d.turn.turn_id).errors.join('\n'),/Document eliminat sense relleu|sense àncora/);
  handoffDocument(root,d.turn.turn_id,d.file,desti);
  bindPlan(root,d.turn.turn_id,plan.file);
  // El rebut conserva la identitat; l'àncora ha de seguir el camí exacte nou.
  // L'enllaç pla anterior no pot acreditar un homònim fora de l'Escriptori.
  assert.match(checkTurn(root,d.turn.turn_id).errors.join('\n'),/Document sense àncora/);
  const index=path.join(root,'_wiki_de_poble/04_escriptori/00_index_escriptori.md');
  const anterior=`[[${path.basename(d.file,'.md')}]]`;
  const nova=`[[../10_actes/${path.basename(desti)}]]`;
  const text=fs.readFileSync(index,'utf8');
  assert.ok(text.includes(anterior),'la fixture ha de contindre l’àncora original');
  fs.writeFileSync(index,text.replace(anterior,nova));
  const r=checkTurn(root,d.turn.turn_id);
  assert.equal(r.valid,true,`el torn ha de sobreviure al moviment: ${r.errors.join(' | ')}`);
});

test('P-2 · el relleu no pot promoure res cap a la zona humana',t=>{
  const {root,d}=planned(t);
  const desti=`${HUMAN}/${path.basename(d.file)}`;
  fs.mkdirSync(path.join(root,HUMAN),{recursive:true});
  fs.renameSync(path.join(root,d.file),path.join(root,desti));
  assert.throws(()=>handoffDocument(root,d.turn.turn_id,d.file,desti),/Zona humana protegida/);
});

// ── P-3 · El Somiador respecta la taula? ───────────────────────────────────────
function somia(root) {
  return spawnSync(process.execPath,[path.join(REPO,'tooling/brain/somiador.mjs'),'--dry-run'],
    {cwd:root,encoding:'utf8'});
}
test('P-3 · en sec, el Somiador no s’endú cap document d’un torn obert',t=>{
  const {root,d}=planned(t);
  const p=somia(root);
  assert.equal(p.status,0,`el Somiador s’ha estavellat: ${p.stderr}`);
  assert.ok(!p.stdout.includes('[DRY-RUN]'),`no havia de moure res i mou: ${p.stdout}`);
  assert.ok(!p.stdout.includes(path.basename(d.file)),p.stdout);
});

test('P-3 · i la prova sap posar-se roja: un fitxer sense torn ni àncora sí que se l’endú',t=>{
  const {root}=planned(t);
  const orfe='260922_0301_informe_orfe.md';
  fs.writeFileSync(path.join(root,'_wiki_de_poble/04_escriptori',orfe),'sense rebut ni àncora\n');
  const p=somia(root);
  assert.equal(p.status,0,p.stderr);
  assert.ok(p.stdout.includes(orfe),`el Somiador havia de proposar endur-se l’orfe: ${p.stdout}`);
});

test('P-3 · un registre de torn corrupte atura el Somiador amb nom propi',t=>{
  const {root}=planned(t);
  fs.writeFileSync(path.join(root,'.agents/runtime/turns/torn_00000000-0000-4000-8000-000000000000.json'),'{}');
  const p=somia(root);
  assert.notEqual(p.status,0,'amb un registre il·legible el Somiador ha de fallar tancat');
  assert.match(p.stderr,/Torn il·legible/);
});

// ── P-4 · La plantilla és el contracte? ────────────────────────────────────────
test('P-4 · els encapçalaments de cada plantilla són exactament les seccions de la seua ruta',t=>{
  const root=fixture(t);
  const {router}=loadContract(root);
  for(const route of router.rutes) {
    const body=fs.readFileSync(path.join(root,route.plantilla),'utf8').replace(/^---[\s\S]*?\n---\n/,'');
    assert.deepEqual([...sections(body).keys()],route.seccions,
      `${route.id}: la plantilla i el contracte han de dir el mateix, en el mateix ordre`);
  }
});

test('P-4 · canviar un encapçalament de la plantilla posa la porta roja',t=>{
  const root=marcaArrel(fixture(t));
  const route=loadContract(root).router.rutes.find(r=>r.id==='prompt.local');
  const file=path.join(root,route.plantilla);
  // L'encapçalament a mutar es deriva del contracte, mai d'un nom literal: quan
  // la plantilla va passar de «Tasca» a «Tasques» (260923), una mutació escrita
  // a mà va deixar de mutar res i la prova declarava verda una porta sense provar.
  const original=route.seccions.find(s=>s==='Registre')??route.seccions[0];
  const patro=new RegExp(`^## ${original.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}$`,'m');
  fs.writeFileSync(file,fs.readFileSync(file,'utf8').replace(patro,`## ${original} mutat`));
  const body=fs.readFileSync(file,'utf8').replace(/^---[\s\S]*?\n---\n/,'');
  assert.notDeepEqual([...sections(body).keys()],route.seccions,'la divergència ha de ser visible');
  const p=spawnSync(process.execPath,[path.join(REPO,'tooling/gates/porta-plantilles.mjs'),'--arrel',root],{encoding:'utf8'});
